class ConfPlantillaNominal extends BaseConfPlantillaNominal {

    /**
     * Obtener una busqueda de los datos de la plantilla nominal dado un texto.
	 *
     * @param int $identidad  Identificador de la entidad.
     * @return array Listado de los datos de las plantillas nominales.
     */
    public static function buscarPlantillNominal($identidad, $textobuscar) {
        
        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->from('ConfPlantillaNominal')
                ->where("identidad = ? and denominacion ilike '%".$textobuscar."%'", array($identidad))
                ->fetchArray();
	}
	
	/**
     * Obtener un listado de los datos de las plantillas nominales dado un identificador de entidad.
	 *
     * @param int $identidad  Identificador de la entidad.
     * @return array Listado de los datos de las plantillas nominales.
     */
    public static function obtenerListadoPlantillasNominales($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->select('cpn.*,na.denominacion as area')
                ->from('ConfPlantillaNominal cpn')
				->leftJoin('cpn.NomAreas na')
                ->where('identidad = ?', array($identidad))
                ->orderBy('orden ASC')
                ->fetchArray();
    }

    /**
     * Obtener un listado de los datos de las plantillas nominales dado un identificador de entidad.
     *
     * @param int $identidad  Identificador de la entidad.
     * @return array Listado de los datos de las plantillas nominales.
     */
    public static function obtenerListadoDenominacionporEntidad($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
            ->select('denominacion')
            ->from('ConfPlantillaNominal')
            ->where('identidad = ? and esbrigada = 1', array($identidad))
            ->orderBy('orden ASC')
            ->fetchArray();
    }
	
	
	/**
     * Verificar si existe la  plantilla nominal dado un identificador de entidad y la denominacion.
	 *
     * @param int $identidad  Identificador de la entidad.
     * @return array Listado de los datos de las plantillas nominales.
     */
    public static function verifyExistPlantilla($identidad,$denom) {
        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        $arrdatosplatilla = Doctrine_Query::create()
                ->from('ConfPlantillaNominal')
                ->where('identidad = ? and denominacion = ?', array($identidad, $denom))
                ->fetchArray();
	    $existe = (count($arrdatosplatilla)>0)?true:false;
		return $existe;
	}

    public static function verifyExistPlantillaxIdEstructuraSincroniza($idestructurasincroniza) {
        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        $arrdatosplatilla = Doctrine_Query::create()
            ->from('ConfPlantillaNominal')
            ->where('idestructurasincroniza = ?', array($idestructurasincroniza))
            ->fetchArray();
        $existe = (count($arrdatosplatilla)>0)?true:false;
        return $existe;
    }

    public static function obtenerListadoPlantillasNominalesSincronizadas($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
            ->select('idplantillanominal, idestructurasincroniza')
            ->from('ConfPlantillaNominal')
            ->where('identidad = ? and idestructurasincroniza is not null', array($identidad))
            ->fetchArray();
    }
    
    public static function obtenerListadoPlantillasNominalesfechanull($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->from('ConfPlantillaNominal')
                ->where('identidad = ? and fechafin is null', array($identidad))
                ->orderBy('orden ASC')
                ->fetchArray();
    }
    
	public static function obtenerListadoIdPlantillasNominales($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->select('idplantillanominal as idplantillanominal')
                ->from('ConfPlantillaNominal')
                ->where('identidad = ?', array($identidad))
                ->orderBy('orden ASC')
                ->fetchArray();
    }
	
    public static function obtenerListadoPlantillasNominalesActivas($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->from('ConfPlantillaNominal')
                ->where('identidad = ? and (fechafin is null or fechafin >= now())', array($identidad))
                ->orderBy('orden ASC')
                ->fetchArray();
    }
	
	
	public static function obtenerDenomXId($idplantillanominal) {
        //Devolviendo la denominacion de la plantilla nominal.
		return Doctrine_Query::create()->select('(p.codigo ||'-'|| p.denominacion) AS denominacion')
                        ->from('ConfPlantillaNominal p')
                        ->where('p.idplantillanominal = ?', array($idplantillanominal))
                        ->fetchOne()
                        ->denominacion;

   }

    public static function obtenerDenomXIdSinCodigo($idplantillanominal) {
        //Devolviendo la denominacion de la plantilla nominal.
        return Doctrine_Query::create()->select('denominacion')
            ->from('ConfPlantillaNominal p')
            ->where('p.idplantillanominal = ?', array($idplantillanominal))
            ->fetchOne()
            ->denominacion;
    }

    public static function obtenerIdentidadxPlantilla($idplantillanominal) {
        //Devolviendo la denominacion de la plantilla nominal.
        return Doctrine_Query::create()->select('identidad')
            ->from('ConfPlantillaNominal p')
            ->where('p.idplantillanominal = ?', array($idplantillanominal))
            ->fetchOne()
            ->identidad;
    }

    /**
     * Obtener la plantilla nominal dado el identificador.
     * 
     * @param $idplantilla        		Identificador de la plantilla nominal.
     * @return ConfPlantillaNominal   	Objeto plantilla nominal (clase del dominio).
     */
    public static function obtenerObjPlantillaNominalDadoId($idplantilla) {
        return Doctrine::getTable('ConfPlantillaNominal')->find($idplantilla);
    }

    public static function obtenerOrdenYDenominacionXId($idplantillanominal) {
        //Devolviendo el orden y la denominacion de la plantilla nominal.
        return Doctrine_Query::create()->select('p.orden, p.denominacion')
            ->from('ConfPlantillaNominal p')
            ->where('p.idplantillanominal = ?', array($idplantillanominal))
            ->fetchArray();
    }

    public static function obtenerOrdenPlantillaXId($idplantillanominal) {
        //Devolviendo la denominacion de la plantilla nominal.
        return Doctrine_Query::create()->select('p.orden AS orden')
            ->from('ConfPlantillaNominal p')
            ->where('p.idplantillanominal = ?', array($idplantillanominal))
            ->fetchOne()
            ->orden;

    }
}
